create table if not exists public.schools (
  id uuid primary key default gen_random_uuid(),
  source_code text not null unique,
  name text not null,
  street text not null default '',
  street_number text not null default '',
  neighborhood text not null default '',
  locality text not null default '',
  department text not null default '',
  phone text not null default '',
  region text not null default '',
  sector text not null default '',
  scope text not null default '',
  category text not null default '',
  permanence text not null default '',
  operating_period text not null default '',
  email text not null default '',
  is_active boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index if not exists schools_name_idx on public.schools(name);
create index if not exists schools_locality_idx on public.schools(locality);
create index if not exists schools_department_idx on public.schools(department);
create index if not exists schools_is_active_idx on public.schools(is_active);

drop trigger if exists set_schools_updated_at on public.schools;
create trigger set_schools_updated_at
before update on public.schools
for each row
execute function app_private.set_updated_at();

