alter table public.profiles
add column if not exists school_id uuid references public.schools(id) on delete set null;

create index if not exists profiles_school_id_idx on public.profiles(school_id);

alter table public.public_profiles
add column if not exists school_id uuid references public.schools(id) on delete set null;

create index if not exists public_profiles_school_id_idx on public.public_profiles(school_id);

create or replace function app_private.sync_profile_school_name()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  update public.profiles
  set school = new.name
  where school_id = new.id;

  return new;
end;
$$;

revoke all on function app_private.sync_profile_school_name() from public;

drop trigger if exists sync_profile_school_name on public.schools;
create trigger sync_profile_school_name
after update of name on public.schools
for each row
execute function app_private.sync_profile_school_name();

create or replace function app_private.clear_deleted_school_from_profiles()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  update public.profiles
  set
    school_id = null,
    school = ''
  where school_id = old.id;

  return old;
end;
$$;

revoke all on function app_private.clear_deleted_school_from_profiles() from public;

drop trigger if exists clear_deleted_school_from_profiles on public.schools;
create trigger clear_deleted_school_from_profiles
before delete on public.schools
for each row
execute function app_private.clear_deleted_school_from_profiles();

with matched_schools as (
  select distinct on (upper(trim(name)))
    id,
    name,
    upper(trim(name)) as normalized_name
  from public.schools
  order by upper(trim(name)), source_code
)
update public.profiles
set
  school_id = matched_schools.id,
  school = matched_schools.name
from matched_schools
where public.profiles.school_id is null
  and upper(trim(public.profiles.school)) = matched_schools.normalized_name;

create or replace function app_private.handle_new_user()
returns trigger
language plpgsql
security definer
set search_path = public, auth, pg_temp
as $$
declare
  requested_school_id text;
  selected_school_id uuid;
  selected_school_name text;
begin
  requested_school_id := coalesce(new.raw_user_meta_data ->> 'school_id', '');

  if requested_school_id ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
    select id, name
    into selected_school_id, selected_school_name
    from public.schools
    where id = requested_school_id::uuid
      and is_active = true;
  end if;

  insert into public.profiles (id, email, name, school_id, school, course)
  values (
    new.id,
    coalesce(new.email, ''),
    coalesce(nullif(new.raw_user_meta_data ->> 'name', ''), split_part(coalesce(new.email, ''), '@', 1)),
    selected_school_id,
    coalesce(selected_school_name, ''),
    coalesce(new.raw_user_meta_data ->> 'course', '')
  )
  on conflict (id) do update
  set
    email = excluded.email,
    name = excluded.name,
    school_id = excluded.school_id,
    school = excluded.school,
    course = excluded.course;

  return new;
end;
$$;

revoke all on function app_private.handle_new_user() from public;

create or replace function app_private.sync_public_profile()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  insert into public.public_profiles (user_id, school_id, name, school, course, is_active, updated_at)
  values (new.id, new.school_id, new.name, new.school, new.course, new.is_active, now())
  on conflict (user_id) do update
  set
    school_id = excluded.school_id,
    name = excluded.name,
    school = excluded.school,
    course = excluded.course,
    is_active = excluded.is_active,
    updated_at = excluded.updated_at;

  return new;
end;
$$;

revoke all on function app_private.sync_public_profile() from public;

drop trigger if exists sync_public_profile on public.profiles;
create trigger sync_public_profile
after insert or update of name, school_id, school, course, is_active
on public.profiles
for each row
execute function app_private.sync_public_profile();

insert into public.public_profiles (user_id, school_id, name, school, course, is_active)
select id, school_id, name, school, course, is_active
from public.profiles
on conflict (user_id) do update
set
  school_id = excluded.school_id,
  name = excluded.name,
  school = excluded.school,
  course = excluded.course,
  is_active = excluded.is_active,
  updated_at = now();

alter table public.schools enable row level security;

grant select on public.schools to anon, authenticated;
grant insert, update, delete on public.schools to authenticated;

drop policy if exists "Anyone can view active schools" on public.schools;
create policy "Anyone can view active schools"
on public.schools
for select
to anon, authenticated
using (is_active = true);

drop policy if exists "Admins can view all schools" on public.schools;
create policy "Admins can view all schools"
on public.schools
for select
to authenticated
using ((select app_private.is_admin()));

drop policy if exists "Admins can insert schools" on public.schools;
create policy "Admins can insert schools"
on public.schools
for insert
to authenticated
with check ((select app_private.is_admin()));

drop policy if exists "Admins can update schools" on public.schools;
create policy "Admins can update schools"
on public.schools
for update
to authenticated
using ((select app_private.is_admin()))
with check ((select app_private.is_admin()));

drop policy if exists "Admins can delete schools" on public.schools;
create policy "Admins can delete schools"
on public.schools
for delete
to authenticated
using ((select app_private.is_admin()));

create or replace view public.leaderboard
with (security_invoker = true)
as
with last_played as (
  select
    user_id,
    max(completed_at) as last_played_at
  from public.game_results
  group by user_id
),
totals as (
  select
    public_profiles.user_id,
    public_profiles.name,
    public_profiles.school_id,
    public_profiles.school,
    public_profiles.course,
    coalesce(sum(game_results.score), 0)::integer as score,
    count(game_results.stage_id)::integer as completed_stages,
    last_played.last_played_at
  from public.public_profiles
  left join public.game_results on game_results.user_id = public_profiles.user_id
  left join last_played on last_played.user_id = public_profiles.user_id
  where public_profiles.is_active = true
  group by
    public_profiles.user_id,
    public_profiles.name,
    public_profiles.school_id,
    public_profiles.school,
    public_profiles.course,
    last_played.last_played_at
)
select
  row_number() over (
    order by score desc, completed_stages desc, last_played_at asc nulls last, name asc
  )::integer as position,
  user_id,
  name,
  school,
  course,
  score,
  completed_stages,
  last_played_at,
  school_id
from totals;

grant select on public.leaderboard to authenticated;
